action.script:
# NotchAny Agent Monitor - widget data script (interpreter=python).
# Two agents, two data paths:
#   Claude Code - session status files written by the bundled hook (push).
#   Codex (CLI + desktop app) - read-only tail of ~/.codex/sessions rollout
#     JSONL, which both surfaces write; nothing to install, nothing to configure.
# Renders both as widget state + notch notifications, and installs/removes the
# Claude hook (embedded below as base64) into ~/.claude/settings.json on demand.
import base64
import glob
import json
import os
import plistlib
import re
import shutil
import subprocess
import time

ROOT = os.path.expanduser("~/.notchany/assets/agent-monitor")
STATE_DIR = os.path.join(ROOT, "state")
HOOK_PATH = os.path.join(ROOT, "agent_monitor_hook.py")
SETTINGS_PATH = os.path.expanduser("~/.claude/settings.json")
CACHE_PATH = os.path.join(ROOT, "notify_cache.json")
NUDGE_PATH = os.path.join(STATE_DIR, ".nudge")
TAG = "agent_monitor_hook.py"
HOOK_B64 = ""

CODEX_HOME = os.environ.get("CODEX_HOME") or os.path.expanduser("~/.codex")
CODEX_SESS = os.path.join(CODEX_HOME, "sessions")
CODEX_INDEX = os.path.join(CODEX_HOME, "session_index.jsonl")
CODEX_CACHE = os.path.join(ROOT, "codex_cache.json")
CODEX_DISMISS = os.path.join(ROOT, "codex_dismissed.json")
CX = "cx:"  # widget-side session key prefix, routes clear/focus to Codex

HOOK_EVENTS = [
    ("UserPromptSubmit", None),
    ("PostToolUse", "*"),
    ("Notification", None),
    ("Stop", None),
    ("SessionEnd", None),
]

try:
    PARAMS = json.loads(os.environ.get("NOTCH_PARAMS") or "{}")
except Exception:
    PARAMS = {}

NOTIFY_AFTER = float(PARAMS.get("notify_after", 20))
DONE_KEEP = float(PARAMS.get("done_keep", 30)) * 60
AGGREGATE = bool(PARAMS.get("aggregate", False))
CODEX_ON = PARAMS.get("codex", True) not in (False, 0, "0", "false")
CODEX_KEEP = float(PARAMS.get("codex_keep", 180)) * 60
CODEX_EVENT_MAX = 600  # only announce Codex turns that finished this recently


def read_json(path, fallback):
    try:
        with open(path) as f:
            return json.load(f)
    except Exception:
        return fallback


def write_json_atomic(path, obj):
    tmp = path + ".tmp"
    with open(tmp, "w") as f:
        json.dump(obj, f, ensure_ascii=False, indent=2)
    os.replace(tmp, path)


def hook_source():
    return base64.b64decode(HOOK_B64).decode("utf-8")


def write_hook_file():
    os.makedirs(STATE_DIR, exist_ok=True)
    src = hook_source()
    try:
        with open(HOOK_PATH) as f:
            if f.read() == src:
                return
    except Exception:
        pass
    with open(HOOK_PATH, "w") as f:
        f.write(src)
    os.chmod(HOOK_PATH, 0o755)


def is_our_entry(entry):
    if not isinstance(entry, dict):
        return False
    return any(
        TAG in (h.get("command") or "")
        for h in (entry.get("hooks") or [])
        if isinstance(h, dict)
    )


def strip_ours(hooks):
    for ev in list(hooks.keys()):
        arr = hooks.get(ev)
        if not isinstance(arr, list):
            continue
        kept = [e for e in arr if not is_our_entry(e)]
        if kept:
            hooks[ev] = kept
        else:
            hooks.pop(ev)


def settings_has_ours():
    settings = read_json(SETTINGS_PATH, {})
    hooks = settings.get("hooks") if isinstance(settings, dict) else None
    if not isinstance(hooks, dict):
        return False
    return any(
        is_our_entry(e)
        for arr in hooks.values()
        if isinstance(arr, list)
        for e in arr
    )


def install_hooks():
    write_hook_file()
    settings = read_json(SETTINGS_PATH, None)
    if not isinstance(settings, dict):
        settings = {}
    backup = SETTINGS_PATH + ".agent-monitor.bak"
    if os.path.exists(SETTINGS_PATH) and not os.path.exists(backup):
        try:
            shutil.copy2(SETTINGS_PATH, backup)
        except Exception:
            pass
    hooks = settings.setdefault("hooks", {})
    strip_ours(hooks)
    cmd = '/usr/bin/env python3 "$HOME/.notchany/assets/agent-monitor/agent_monitor_hook.py"'
    for ev, matcher in HOOK_EVENTS:
        entry = {"hooks": [{"type": "command", "command": cmd, "timeout": 10}]}
        if matcher is not None:
            entry["matcher"] = matcher
        hooks.setdefault(ev, []).append(entry)
    os.makedirs(os.path.dirname(SETTINGS_PATH), exist_ok=True)
    write_json_atomic(SETTINGS_PATH, settings)


def uninstall_hooks():
    settings = read_json(SETTINGS_PATH, None)
    if not isinstance(settings, dict):
        return
    hooks = settings.get("hooks")
    if isinstance(hooks, dict):
        strip_ours(hooks)
        if not hooks:
            settings.pop("hooks", None)
        write_json_atomic(SETTINGS_PATH, settings)


def ensure_hook_fresh():
    # auto-upgrade the installed hook file after a package update
    if settings_has_ours():
        try:
            write_hook_file()
        except Exception:
            pass


def collect(now):
    os.makedirs(STATE_DIR, exist_ok=True)
    sessions, ended = [], []

    def drop(path, sid):
        ended.append(sid)
        try:
            os.remove(path)
        except OSError:
            pass

    for fn in sorted(os.listdir(STATE_DIR)):
        if not fn.endswith(".json"):
            continue
        path = os.path.join(STATE_DIR, fn)
        st = read_json(path, None)
        if not isinstance(st, dict):
            drop(path, fn[:-5])
            continue
        sid = str(st.get("session_id") or fn[:-5])
        state = st.get("state") or "running"
        upd = float(st.get("updated_at") or 0)
        # terminal sessions stay listed for manual cleanup; DONE_KEEP is the
        # auto-expiry fallback, orphaned running sessions are purged after 2h
        if state == "ended" and now - upd > DONE_KEEP:
            drop(path, sid)
            continue
        if state == "done" and now - float(st.get("done_at") or upd) > DONE_KEEP:
            drop(path, sid)
            continue
        if state not in ("done", "ended") and now - upd > 2 * 3600:
            drop(path, sid)
            continue
        steps = st.get("steps") or []
        total = len(steps)
        done_n = sum(1 for s in steps if s.get("status") == "completed")
        current = ""
        for s in steps:
            if s.get("status") == "in_progress":
                current = s.get("active") or s.get("name") or ""
                break
        sessions.append({
            "sid8": sid[:8],
            "project": st.get("project") or "session",
            "root": st.get("root") or "",
            "cwd": st.get("cwd") or "",
            "agent": st.get("agent") or "claude-code",
            "state": state,
            "stale": state not in ("done", "ended") and now - upd > 600,
            "prompt": st.get("prompt") or "",
            "message": st.get("message") or "",
            "last_message": st.get("last_message") or "",
            "current": current,
            "done": done_n,
            "total": total,
            "tools": 0,
            "edits": 0,
            "kids": 0,
            "started_at": float(st.get("started_at") or upd),
            "done_at": float(st.get("done_at") or 0),
            "prompt_id": str(st.get("prompt_id") or "p0"),
            "has_host": bool(st.get("host")),
        })
    order = {"waiting": 0, "running": 1, "done": 2, "ended": 3}
    sessions.sort(key=lambda s: (order.get(s["state"], 1), -s["started_at"]))
    return sessions, ended


# --------------------------------------------------------------------------
# Codex (CLI + desktop app). Both write ~/.codex/sessions/<y>/<m>/<d>/rollout-
# <ts>-<session_id>.jsonl as the turn progresses, so tailing them needs no hook
# and no config change. Nothing here ever writes into ~/.codex.
# --------------------------------------------------------------------------
CX_HEAD_BYTES = 384 * 1024
CX_CHUNK = 256 * 1024
CX_MAX_SCAN = 24 * 1024 * 1024  # backstop for a pathologically long single turn
CX_HEAD_LINES = 60
CX_TEXT = 100
CX_UUID = re.compile(r"\A[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\Z")

RE_SID = re.compile(r'"session_id"\s*:\s*"([0-9a-fA-F-]{8,})"')
RE_CWD = re.compile(r'"cwd"\s*:\s*"((?:[^"\\]|\\.)*)"')
RE_ORIG = re.compile(r'"originator"\s*:\s*"([^"]{0,40})"')
RE_PARENT = re.compile(r'"parent_thread_id"\s*:\s*"([0-9a-fA-F-]{8,})"')
RE_SUB = re.compile(r'"subagent"')


def cx_clip(text):
    return (text or "").strip().replace("\n", " ")[:CX_TEXT]


def project_root(cwd):
    d = cwd
    while d and d != "/":
        if os.path.exists(os.path.join(d, ".git")):
            return d
        d = os.path.dirname(d)
    return cwd


def cx_meta(head):
    """session_meta is a single multi-KB line (base_instructions is inlined);
    every field we need precedes it, so regex the front instead of parsing it."""
    sid = RE_SID.search(head)
    cwd = RE_CWD.search(head)
    orig = RE_ORIG.search(head)
    par = RE_PARENT.search(head)
    try:
        cwd_s = json.loads('"%s"' % cwd.group(1)) if cwd else ""
    except Exception:
        cwd_s = ""
    return {
        "sid": sid.group(1) if sid else "",
        "cwd": cwd_s,
        "orig": orig.group(1) if orig else "",
        "sub": bool(RE_SUB.search(head)),
        "parent": par.group(1) if par else "",
    }


def cx_user_text(item):
    for c in item.get("content") or []:
        if isinstance(c, dict) and c.get("text"):
            return cx_clip(c["text"])
    return ""


def cx_item_label(item):
    t = item.get("type")
    if t == "CommandExecution":
        parsed = item.get("parsed_cmd") or []
        if parsed and isinstance(parsed[0], dict) and parsed[0].get("cmd"):
            return cx_clip(str(parsed[0]["cmd"]))
        cmd = item.get("command") or []
        return cx_clip(str(cmd[-1])) if isinstance(cmd, list) and cmd else "command"
    if t == "FileChange":
        names = [os.path.basename(p) for p in list(item.get("changes") or {})[:2]]
        return ("✎ " + ", ".join(names)) if names else "✎"
    if t in ("AgentMessage", "Reasoning"):
        if t == "AgentMessage":
            return cx_user_text(item)
        s = item.get("summary_text") or []
        return cx_clip(re.sub(r"\*+", "", s[0])) if s else ""
    if t == "ContextCompaction":
        return "compacting context"
    return ""


def cx_first_prompt(head):
    """Opening prompt; `codex exec` runs are single-turn so this is the only one
    (multi-turn sessions get a newer prompt out of the tail scan instead)."""
    for raw in head.split("\n")[1:CX_HEAD_LINES]:
        if '"user_message"' not in raw and '"UserMessage"' not in raw:
            continue
        try:
            p = json.loads(raw).get("payload") or {}
        except Exception:
            continue
        if p.get("type") == "user_message":
            return cx_clip(p.get("message") or "")
        if p.get("type") == "item_completed":
            it = p.get("item") or {}
            if it.get("type") == "UserMessage":
                return cx_user_text(it)
    return ""


def rev_lines(fh, size):
    """Yield whole lines from the end of the file backwards, reading only as far
    back as the consumer pulls. A single turn can append megabytes, so a fixed
    tail window would miss the `task_started` of a long-running one."""
    pos, buf, read = size, b"", 0
    while pos > 0 and read < CX_MAX_SCAN:
        step = min(CX_CHUNK, pos)
        pos -= step
        fh.seek(pos)
        chunk = fh.read(step)
        read += step
        buf = chunk + buf
        parts = buf.split(b"\n")
        buf = parts[0]  # possibly truncated at the chunk boundary; carry it over
        for line in reversed(parts[1:]):
            yield line.decode("utf-8", "replace")
    if pos == 0 and buf:
        yield buf.decode("utf-8", "replace")


def cx_tail(lines):
    """Walk backwards from the end of the rollout to the newest turn boundary."""
    st = {"turn": "", "started": 0.0, "done_at": 0.0, "prompt": "",
          "last_message": "", "current": "", "tools": 0, "edits": 0}
    ended = False
    for raw in lines:
        # cheap prefilter: reasoning / tool-output records are the bulk of the
        # file and none of them are event_msg, so never pay to parse them
        if not raw.startswith("{") or '"event_msg"' not in raw:
            continue
        try:
            o = json.loads(raw)
        except Exception:
            continue
        if o.get("type") != "event_msg":
            continue
        p = o.get("payload") or {}
        t = p.get("type")
        if t == "task_complete" and not st["turn"]:
            st.update(turn="done", done_at=float(p.get("completed_at") or 0),
                      started=float(p.get("started_at") or 0),
                      last_message=cx_clip(p.get("last_agent_message") or ""))
            ended = True
        elif t == "turn_aborted" and not st["turn"]:
            st.update(turn="aborted", done_at=float(p.get("completed_at") or 0),
                      started=float(p.get("started_at") or 0))
            ended = True
        elif t == "task_started":
            if not st["turn"]:
                st["turn"] = "running"
            if not st["started"]:
                st["started"] = float(p.get("started_at") or 0)
            break  # anything older belongs to the previous turn
        elif t == "user_message" and not st["prompt"]:
            st["prompt"] = cx_clip(p.get("message") or "")
        elif t == "item_completed":
            it = p.get("item") or {}
            k = it.get("type")
            if k == "CommandExecution":
                st["tools"] += 1
            elif k == "FileChange":
                st["edits"] += 1
            elif k == "UserMessage" and not st["prompt"]:
                st["prompt"] = cx_user_text(it)
            if k == "AgentMessage" and ended and not st["last_message"]:
                st["last_message"] = cx_item_label(it)
            if not ended and not st["current"]:
                st["current"] = cx_item_label(it)
    if st["turn"] != "running":
        st["current"] = ""
    return st


def cx_parse(path):
    with open(path, "rb") as fh:
        head = fh.read(CX_HEAD_BYTES).decode("utf-8", "replace")
        meta = cx_meta(head)
        if not meta["sid"]:
            return None
        rec = {"meta": meta}
        if not meta["sub"]:
            size = fh.seek(0, 2)
            st = cx_tail(rev_lines(fh, size))
            if not st["prompt"]:
                st["prompt"] = cx_first_prompt(head)
            rec["turn"] = st
    return rec


def cx_titles():
    """Desktop threads get an auto-generated name; nicer than the raw prompt."""
    names = {}
    try:
        with open(CODEX_INDEX, errors="replace") as fh:
            for line in fh:
                try:
                    o = json.loads(line)
                except Exception:
                    continue
                if o.get("id") and o.get("thread_name"):
                    names[o["id"]] = cx_clip(o["thread_name"])
    except OSError:
        pass
    return names


def cx_agent(orig):
    if "desktop" in orig.lower() or "app" in orig.lower():
        return "codex-app"
    if "exec" in orig.lower():
        return "codex-exec"
    return "codex-cli"


def cx_scan(now, window):
    """Parse every rollout touched inside `window`, memoised on (size, mtime)."""
    cache = read_json(CODEX_CACHE, {})
    if not isinstance(cache, dict):
        cache = {}
    fresh, rows, kids = {}, {}, {}
    cutoff = now - window
    for path in glob.glob(os.path.join(CODEX_SESS, "*", "*", "*", "rollout-*.jsonl")):
        try:
            stt = os.stat(path)
        except OSError:
            continue
        if stt.st_mtime < cutoff:
            continue
        sig = "%d:%d" % (stt.st_size, int(stt.st_mtime))
        hit = cache.get(path)
        if isinstance(hit, dict) and hit.get("sig") == sig:
            rec = hit.get("rec")
        else:
            try:
                rec = cx_parse(path)
            except OSError:
                continue
        if not rec:
            continue
        fresh[path] = {"sig": sig, "rec": rec}
        meta = rec["meta"]
        if meta["sub"]:
            kids[meta["parent"]] = kids.get(meta["parent"], 0) + 1
            continue
        rec = dict(rec, mtime=stt.st_mtime, path=path)
        rows[meta["sid"]] = rec
    if fresh != cache:  # the poll runs every few seconds; don't churn the disk
        try:
            write_json_atomic(CODEX_CACHE, fresh)
        except OSError:
            pass
    return rows, kids


def cx_dismissed():
    d = read_json(CODEX_DISMISS, {})
    return d if isinstance(d, dict) else {}


def cx_dismiss(keys, now):
    d = cx_dismissed()
    for k in keys:
        d[k] = now
    # entries only matter while the session is still inside the display window
    for k in [k for k, v in d.items() if now - float(v or 0) > max(CODEX_KEEP, 86400)]:
        d.pop(k, None)
    try:
        write_json_atomic(CODEX_DISMISS, d)
    except OSError:
        pass


def collect_codex(now):
    if not CODEX_ON or not os.path.isdir(CODEX_SESS):
        return []
    # running turns are kept regardless of age; finished ones age out of the
    # window (their files are Codex's, so we never delete anything)
    rows_raw, kids = cx_scan(now, max(CODEX_KEEP, 3600) + 6 * 3600)
    titles = cx_titles()
    gone = cx_dismissed()
    out = []
    for sid, rec in rows_raw.items():
        meta, st = rec["meta"], rec["turn"]
        idle = now - rec["mtime"]
        turn = st["turn"] or "aborted"
        if turn == "running":
            state, stale = "running", idle > 600
        elif turn == "done":
            state, stale = "done", False
        else:
            state, stale = "ended", False
        started = st["started"] or rec["mtime"]
        pid_ = "t%d" % int(started or 0)
        key = CX + sid
        if gone.get(key + "|" + pid_):
            continue
        if state != "running" and now - rec["mtime"] > CODEX_KEEP:
            continue
        cwd = meta["cwd"]
        root = project_root(cwd) if cwd else ""
        agent = cx_agent(meta["orig"])
        out.append({
            "sid8": key,
            "project": os.path.basename((root or cwd).rstrip("/")) or "codex",
            "root": root, "cwd": cwd, "agent": agent,
            "state": state, "stale": stale,
            "prompt": st["prompt"] or titles.get(sid, "") or "Codex",
            "message": "", "last_message": st["last_message"],
            "current": st["current"], "done": 0, "total": 0,
            "tools": st["tools"], "edits": st["edits"], "kids": kids.get(sid, 0),
            "started_at": started,
            "done_at": st["done_at"] or (rec["mtime"] if state != "running" else 0),
            "prompt_id": pid_,
            # desktop threads are always reachable by deep link; a terminal
            # session is only locatable while its process still holds the file
            "has_host": agent == "codex-app" or state == "running",
        })
    return out


def bundle_of(path):
    m = re.match(r"(.*?\.app)/Contents/MacOS/", path or "")
    if not m:
        return ""
    try:
        with open(os.path.join(m.group(1), "Contents", "Info.plist"), "rb") as f:
            return str(plistlib.load(f).get("CFBundleIdentifier") or "")
    except Exception:
        return ""


TERM_BY_BUNDLE = {
    "com.apple.Terminal": "Apple_Terminal",
    "com.googlecode.iterm2": "iTerm.app",
    "dev.warp.Warp-Stable": "WarpTerminal",
    "dev.warp.Warp-Preview": "WarpTerminal",
    "com.microsoft.VSCode": "vscode",
    "com.microsoft.VSCodeInsiders": "vscode",
    "com.todesktop.230313mzl4w4u92": "vscode",  # Cursor
}


def cx_host_for(path):
    """Locate the live process that owns this rollout file, then walk its
    ancestors up to the hosting .app so the usual focus paths can be reused."""
    try:
        out = subprocess.run(["lsof", "-w", "-n", "-P", "-c", "codex"],
                             capture_output=True, text=True, timeout=8).stdout
    except Exception:
        return {}
    pid = 0
    for line in out.splitlines():
        if line.rstrip().endswith(path):
            parts = line.split()
            if len(parts) > 1 and parts[1].isdigit():
                pid = int(parts[1])
                break
    if not pid:
        return {}
    host = {"term_program": "", "bundle_id": "", "tty": "", "focus_url": ""}
    cur = pid
    for _ in range(8):
        try:
            fields = subprocess.run(
                ["ps", "-o", "tty=,ppid=,comm=", "-p", str(cur)],
                capture_output=True, text=True, timeout=3,
            ).stdout.strip()
        except Exception:
            break
        if not fields:
            break
        parts = fields.split(None, 2)
        if len(parts) < 3:
            break
        tty, ppid, comm = parts
        if tty and tty != "??" and not host["tty"]:
            host["tty"] = tty
        bundle = bundle_of(comm)
        if bundle and bundle != "com.openai.codex":
            host["bundle_id"] = bundle
            host["term_program"] = TERM_BY_BUNDLE.get(bundle, "")
            break
        if not ppid.isdigit() or int(ppid) <= 1:
            break
        cur = int(ppid)
    return host


def focus_codex(sid, now):
    rows_raw, _ = cx_scan(now, max(CODEX_KEEP, 3600) + 6 * 3600)
    rec = rows_raw.get(sid)
    if not rec:
        return "not_found"
    agent = cx_agent(rec["meta"]["orig"])
    if agent == "codex-app":
        # official desktop deep link; validate the shape before handing it to
        # `open` because the id comes out of a file we do not own
        if not CX_UUID.match(sid):
            return "no_host"
        try:
            subprocess.run(["open", "codex://threads/" + sid],
                           capture_output=True, text=True, timeout=8)
            return "deep_link"
        except Exception:
            return "no_host"
    host = cx_host_for(rec["path"])
    if not host or not (host.get("tty") or host.get("bundle_id")):
        return "no_host"
    return focus_host(host, rec["meta"]["cwd"])


def fmt_elapsed(sec):
    sec = max(0, int(sec))
    if sec < 60:
        return "%ds" % sec
    if sec < 3600:
        return "%dm" % (sec // 60)
    return "%dh%02dm" % (sec // 3600, sec % 3600 // 60)


def build_desired(sessions, now):
    """Desired notification set: (ongoing map id->notif, completion events list)."""
    ongoing = {}
    events = []
    active = [
        s for s in sessions
        if s["state"] in ("running", "waiting")
        and not s["stale"]
        and now - s["started_at"] >= NOTIFY_AFTER
    ]
    if AGGREGATE:
        if active:
            first = min(active, key=lambda s: s["started_at"])
            top = active[0]
            detail = top["project"] + " · " + (
                "%d/%d" % (top["done"], top["total"]) if top["total"]
                else fmt_elapsed(now - top["started_at"])
            )
            notif = {
                "id": "agents",
                "type": "ongoing",
                "activation_id": "agg:%s:%s" % (first["sid8"], first["prompt_id"]),
                "icon": {"symbol": "sparkles"},
                "title": "⚡ %d" % len(active),
                "details": detail[:110],
                "paused": all(s["state"] == "waiting" for s in active),
            }
            if not notif["paused"]:
                notif["spin_period_seconds"] = 6
            ongoing["agents"] = notif
    else:
        for s in active:
            if s["total"]:
                detail = "%s · %d/%d" % (s["current"] or "…", s["done"], s["total"])
            elif s["state"] == "waiting":
                detail = "⏸ " + (s["message"] or "…")
            else:
                detail = (s["current"] or s["prompt"]
                          or fmt_elapsed(now - s["started_at"]))
            if s["state"] == "waiting":
                symbol = "pause.circle"
            elif s["agent"].startswith("codex"):
                symbol = "chevron.left.forwardslash.chevron.right"
            else:
                symbol = "bolt.fill"
            notif = {
                "id": "s-" + s["sid8"],
                "type": "ongoing",
                "activation_id": "%s:%s" % (s["sid8"], s["prompt_id"]),
                "icon": {"symbol": symbol},
                "title": s["project"][:110],
                "details": detail[:110],
                "paused": s["state"] == "waiting",
            }
            if not notif["paused"]:
                notif["spin_period_seconds"] = 6
            ongoing[notif["id"]] = notif
    for s in sessions:
        if s["state"] != "done":
            continue
        duration = (s["done_at"] or now) - s["started_at"]
        if duration < NOTIFY_AFTER and s["total"] == 0:
            continue
        # Claude rows only exist for runs this widget watched, but Codex rows are
        # read back out of its on-disk history - gate them on freshness so a
        # first install (or a long App downtime) can't dump a backlog of unreads
        if s["agent"].startswith("codex") and now - (s["done_at"] or 0) > CODEX_EVENT_MAX:
            continue
        title = "✅ " + s["project"]
        if s["total"]:
            title += " · %d/%d" % (s["done"], s["total"])
        elif duration >= 1:
            title += " · " + fmt_elapsed(duration)
        events.append({
            "id": "done:%s:%s" % (s["sid8"], s["prompt_id"]),
            "type": "event",
            "title": title[:110],
            "details": (s["last_message"] or s["prompt"])[:110],
        })
    return ongoing, events


def load_cache():
    cache = read_json(CACHE_PATH, {})
    if not isinstance(cache, dict):
        cache = {}
    if not isinstance(cache.get("events"), list):
        cache["events"] = []
    if not isinstance(cache.get("ongoing"), dict):
        cache["ongoing"] = {}
    return cache


def dispatch_one(sessions, now):
    """One notification per run (last notch_result call wins), so diff desired
    state against what we already reported and send the top-priority delta.
    Returns (notification|None, more_pending)."""
    cache = load_cache()
    ongoing_desired, events_desired = build_desired(sessions, now)
    pending = []
    for ev in events_desired:
        if ev["id"] not in cache["events"]:
            pending.append(("event", ev, None))
    for oid in cache["ongoing"]:
        if oid not in ongoing_desired:
            pending.append(("end", {"end": oid}, None))
    for oid, notif in ongoing_desired.items():
        sig = [notif.get(k) for k in ("activation_id", "title", "details", "paused")]
        if cache["ongoing"].get(oid) != sig:
            pending.append(("ongoing", notif, sig))
    if not pending:
        return None, False
    kind, item, sig = pending[0]
    if kind == "event":
        cache["events"].append(item["id"])
        cache["events"] = cache["events"][-200:]
    elif kind == "end":
        cache["ongoing"].pop(item["end"], None)
    else:
        cache["ongoing"][item["id"]] = sig
    write_json_atomic(CACHE_PATH, cache)
    return item, len(pending) > 1


TERMINAL_AS = '''
tell application "Terminal"
  activate
  repeat with w in windows
    repeat with t in tabs of w
      if tty of t is equal to "%s" then
        set selected tab of w to t
        set index of w to 1
        return
      end if
    end repeat
  end repeat
end tell
'''

ITERM_AS = '''
tell application "iTerm2"
  activate
  repeat with w in windows
    repeat with tb in tabs of w
      repeat with s in sessions of tb
        if tty of s is equal to "%s" then
          select s
          select tb
          select w
          return
        end if
      end repeat
    end repeat
  end repeat
end tell
'''


WARP_CYCLE_AS = '''
on run argv
  set marker to item 1 of argv
  tell application "System Events"
    set pl to (every process whose bundle identifier contains "warp")
    if (count of pl) = 0 then return "no-proc"
    set p to item 1 of pl
    set frontmost of p to true
    tell p
      try
        set value of attribute "AXEnhancedUserInterface" to true
      end try
      delay 0.25
      set initial to ""
      try
        set initial to value of attribute "AXTitle" of window 1
      end try
      if initial is marker then return "found:0"
      repeat with i from 1 to 24
        keystroke "}" using {command down, shift down}
        delay 0.22
        set t to ""
        try
          set t to value of attribute "AXTitle" of window 1
        end try
        if t is marker then return "found:" & i
        if i > 3 and t is initial then exit repeat
      end repeat
      return "not-found"
    end tell
  end tell
end run
'''


def write_tty_title(dev_tty, title):
    fd = os.open(dev_tty, os.O_WRONLY | os.O_NOCTTY)
    os.write(fd, ("\033]2;" + title + "\007").encode())
    os.close(fd)


def focus_warp(bundle, dev_tty, run, project):
    """Warp has no scripting API: stamp a marker title onto the session's tty
    (OSC 2 goes through the pty like normal output), then cycle tabs with
    Cmd+Shift+} until the window title matches the marker."""
    marker = "NA⚡%d" % (int(time.time()) % 100000)
    try:
        write_tty_title(dev_tty, marker)
    except Exception:
        run(["open", "-b", bundle or "dev.warp.Warp-Stable"])
        return "activated"
    run(["open", "-b", bundle or "dev.warp.Warp-Stable"])
    r = run(["osascript", "-e", WARP_CYCLE_AS, marker], timeout=15)
    try:
        # hand the title back; Claude Code re-sets it on its next activity
        write_tty_title(dev_tty, project or "")
    except Exception:
        pass
    if r is not None and r.returncode != 0 and "-1743" in (r.stderr or ""):
        return "permission_required"
    out = (r.stdout or "").strip() if r else ""
    return "tab_selected" if out.startswith("found") else "activated"


def focus_host(host, cwd):
    """Bring the app hosting this Claude Code session to front; for scriptable
    terminals also select the exact tab by tty. Returns an outcome string."""
    tp = host.get("term_program") or ""
    bundle = host.get("bundle_id") or ""
    tty = host.get("tty") or ""
    dev_tty = ("/dev/" + tty) if tty and not tty.startswith("/dev/") else tty

    def run(cmd, timeout=8):
        try:
            return subprocess.run(cmd, capture_output=True, text=True, timeout=timeout)
        except Exception:
            return None

    if tp == "vscode" and bundle and cwd and os.path.isdir(cwd):
        # focuses the window that has this folder open (VS Code / Cursor etc.)
        run(["open", "-b", bundle, cwd])
        return "activated"
    if tp == "WarpTerminal":
        # Warp v0.2026.05.27+ official deep link: focuses the exact
        # window/pane; validate scheme+shape before open (untrusted file data)
        focus_url = host.get("focus_url") or ""
        if re.fullmatch(r"warp[a-z]{0,16}://session/[0-9a-f]{32}", focus_url):
            if run(["open", focus_url]) is not None:
                return "deep_link"
        if dev_tty:
            return focus_warp(bundle, dev_tty, run, os.path.basename(cwd.rstrip("/")))
    activated = False
    if bundle:
        activated = run(["open", "-b", bundle]) is not None
    elif tp == "Apple_Terminal":
        activated = run(["open", "-a", "Terminal"]) is not None
    elif tp == "iTerm.app":
        activated = run(["open", "-a", "iTerm"]) is not None
    if dev_tty and tp in ("Apple_Terminal", "iTerm.app"):
        script = (TERMINAL_AS if tp == "Apple_Terminal" else ITERM_AS) % dev_tty
        r = run(["osascript", "-e", script])
        if r is not None and r.returncode != 0 and "-1743" in (r.stderr or ""):
            return "permission_required"
        if r is not None and r.returncode == 0:
            return "tab_selected"
    return "activated" if activated else "no_host"


def focus_session(sid, now):
    if sid.startswith(CX):
        return focus_codex(sid[len(CX):], now)
    target = None
    if sid and os.path.isdir(STATE_DIR):
        for fn in sorted(os.listdir(STATE_DIR)):
            if fn.endswith(".json") and fn.startswith(sid):
                target = read_json(os.path.join(STATE_DIR, fn), None)
                break
    if not isinstance(target, dict):
        return "not_found"
    host = target.get("host") or {}
    if not host:
        return "no_host"
    return focus_host(host, target.get("cwd") or "")


def nudge():
    # touch a non-json file inside the watched dir so the file trigger re-runs
    # this script ~1s later and the next pending notification gets dispatched
    try:
        with open(NUDGE_PATH, "w") as f:
            f.write(str(time.time()))
    except Exception:
        pass


def widget_state(installed, sessions, now):
    return {
        "installed": installed,
        "codex": CODEX_ON and os.path.isdir(CODEX_SESS),
        "now": now,
        "sessions": sessions,
    }


ORDER = {"waiting": 0, "running": 1, "done": 2, "ended": 3}


def collect_all(now):
    sessions, _ = collect(now)
    try:
        sessions += collect_codex(now)
    except Exception:
        pass  # a malformed rollout must never take the Claude side down
    sessions.sort(key=lambda s: (ORDER.get(s["state"], 1), -s["started_at"]))
    return sessions


def payload():
    try:
        return json.loads(os.environ.get("NOTCH_WIDGET_PAYLOAD") or "{}") or {}
    except Exception:
        return {}


def main():
    op = os.environ.get("NOTCH_WIDGET_EVENT") or ""
    if not op:
        op = {"install": "install-hooks", "uninstall": "uninstall-hooks"}.get(
            str(PARAMS.get("op") or ""), "")
    now = time.time()

    if op in ("clear", "clear-done"):
        drop_cx = []
        if op == "clear":
            sid = str(payload().get("sid") or "")
            if sid.startswith(CX):
                drop_cx = [s["sid8"] + "|" + s["prompt_id"]
                           for s in collect_codex(now) if s["sid8"] == sid]
            elif sid and os.path.isdir(STATE_DIR):
                for fn in os.listdir(STATE_DIR):
                    if fn.endswith(".json") and fn.startswith(sid):
                        try:
                            os.remove(os.path.join(STATE_DIR, fn))
                        except OSError:
                            pass
        else:
            # Codex rollouts belong to Codex, so "clear" only hides the row
            drop_cx = [s["sid8"] + "|" + s["prompt_id"] for s in collect_codex(now)
                       if s["state"] in ("done", "ended") or s["stale"]]
            listing = os.listdir(STATE_DIR) if os.path.isdir(STATE_DIR) else []
            for fn in listing:
                if not fn.endswith(".json"):
                    continue
                path = os.path.join(STATE_DIR, fn)
                st = read_json(path, None)
                if not isinstance(st, dict):
                    continue
                state = st.get("state") or "running"
                upd = float(st.get("updated_at") or 0)
                stale = state not in ("done", "ended") and now - upd > 600
                if state in ("done", "ended") or stale:
                    try:
                        os.remove(path)
                    except OSError:
                        pass
        if drop_cx:
            cx_dismiss(drop_cx, now)
        op = ""  # fall through to the normal status/dispatch flow

    if op == "focus":
        outcome = focus_session(str(payload().get("sid") or ""), now)
        state = widget_state(True, collect_all(now), now)
        state["focus_result"] = outcome
        notch_result(summary="focus:" + outcome, widget=state)
        return

    if op == "install-hooks":
        install_hooks()
        notch_result(
            summary="已接入 Claude Code / Hooks installed",
            widget=widget_state(True, collect_all(now), now),
        )
        return
    if op == "uninstall-hooks":
        uninstall_hooks()
        try:
            os.remove(CACHE_PATH)
        except OSError:
            pass
        notch_result(
            summary="已移除 Claude Code hooks / Hooks removed",
            widget=widget_state(False, collect_codex(now), now),
            notification={"end_all": True},
        )
        return

    ensure_hook_fresh()
    installed = settings_has_ours() and os.path.exists(HOOK_PATH)
    sessions = collect_all(now)
    kwargs = {"widget": widget_state(installed, sessions, now)}
    more = False
    # Codex needs no install, so notifications run as soon as either side is live
    if installed or any(s["agent"].startswith("codex") for s in sessions):
        notif, more = dispatch_one(sessions, now)
        if notif:
            kwargs["notification"] = notif
    notch_result(**kwargs)
    if more:
        nudge()


main()

