  'codex-exec': CODEX_LOGO,
};

const TAGS = { 'codex-app': 'tag_app', 'codex-cli': 'tag_cli', 'codex-exec': 'tag_exec' };

function esc(x) {
  return String(x ?? '').replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
}

function fmtElapsed(sec) {
  if (!isFinite(sec) || sec < 0) return '';
  if (sec < 60) return Math.floor(sec) + 's';
  if (sec < 3600) return Math.floor(sec / 60) + 'm';
  return Math.floor(sec / 3600) + 'h' + Math.floor(sec % 3600 / 60) + 'm';
}

// glyphs picked for a guaranteed monochrome (non-emoji) presentation:
// ▸ commands run, Δ files changed, ⑂ subagents
function counters(x) {
  const b = [];
  if (x.tools) b.push('▸' + x.tools);
  if (x.edits) b.push('Δ' + x.edits);
  if (x.kids) b.push('⑂' + x.kids);
  return b.join(' ');
}

function rowHtml(x, now) {
  const terminal = x.state === 'done' || x.state === 'ended' || x.stale;
  const cls = x.stale ? 'stale' : x.state;
  const stateTxt = x.stale ? t('st_stale') : t('st_' + x.state);
  const primary = x.prompt || stateTxt;
  let sub, prog = '';
  if (x.total > 0) {
    sub = (x.current || stateTxt) + ' · ' + x.done + '/' + x.total;
    const pct = Math.round(100 * x.done / Math.max(1, x.total));
    prog = '<div class="bar"><i style="width:' + pct + '%"></i></div>';
  } else if (x.state === 'running' && x.current) {
    sub = x.current;
  } else if (x.state === 'done') {
    sub = stateTxt + (x.last_message ? ' · ' + x.last_message : '');
  } else if (x.state === 'waiting') {
    sub = stateTxt + (x.message ? ' · ' + x.message : '');
  } else {
    sub = stateTxt;
  }
  // Codex has no todo list, so a live turn shows command / edit / subagent
  // counters instead of a step progress bar; finished rows show their reply
  const cnt = x.state === 'running' ? counters(x) : '';
  if (cnt) sub = sub ? cnt + ' · ' + sub : cnt;
  const el = terminal ? '' : fmtElapsed(now - x.started_at);
  const logo = LOGOS[x.agent] || '🤖';
  const tag = TAGS[x.agent] ? '<span class="tag">' + esc(t(TAGS[x.agent])) + '</span>' : '';
  const tail = terminal
    ? '<span class="clr" data-clear="' + esc(x.sid8) + '">✕</span>'
    : (x.has_host ? '<span class="chev">›</span>' : '');
  return '<div class="row' + (x.has_host ? ' navi' : '') + '" data-sid="' + esc(x.sid8) + '">' +
    '<span class="alogo">' + logo + '</span>' +
    '<span class="dot ' + cls + '"></span><div class="mid">' +
    '<div class="l1"><span class="proj">' + esc(primary) + '</span>' + tag +
