function render(res, force) {
  if (!res || !res.ok || !res.state) return;
  lastRes = res;
  const s = res.state;
  // skip DOM rebuild when nothing changed (elapsed times tick per minute) so
  // periodic refreshes don't replace rows out from under an in-flight click
  const key = JSON.stringify([s.installed, s.sessions, Math.floor((s.now || 0) / 60)]);
  if (!force && key === lastKey) return;
  lastKey = key;
  const list = $('#list');
  const count = $('#count');
  const setup = $('#setup');
  const clearBtn = $('#clearDone');
  const hookPill = $('#hookPill');
  const ses = s.sessions || [];
  // Codex needs no install, so the setup panel only takes over the whole widget
  // when neither agent has anything to show; otherwise it shrinks to a pill
  if (!s.installed && !ses.length) {
    setup.classList.add('on');
    list.style.display = 'none';
    count.textContent = '';
    clearBtn.style.display = 'none';
    hookPill.style.display = 'none';
    return;
  }
  setup.classList.remove('on');
  list.style.display = 'flex';
  hookPill.style.display = s.installed ? 'none' : '';
  count.textContent = ses.length ? String(ses.length) : '';
  const hasTerminal = ses.some(x => x.state === 'done' || x.state === 'ended' || x.stale);
  clearBtn.style.display = hasTerminal ? '' : 'none';
  if (!ses.length) {
    list.innerHTML = '<div class="empty"><div>' + esc(t('empty')) +
      '</div><div class="hint">' + esc(t('empty_hint')) + '</div></div>';
    return;
  }
  const groups = new Map();
  for (const x of ses) {
    const k = x.root || x.cwd || x.project;
    if (!groups.has(k)) groups.set(k, []);
    groups.get(k).push(x);
  }
  const ord = { waiting: 0, running: 1, done: 2, ended: 3 };
  const stateOf = x => x.stale ? 'stale' : x.state;
  const glist = [...groups.entries()].map(([k, arr]) => ({
    k, arr, best: Math.min(...arr.map(x => ord[x.state] ?? 1)),
  }));
  glist.sort((a, b) => a.best - b.best);
  let html = '';
  for (const g of glist) {
    const collapsed = !!folds[g.k];
    const activeN = g.arr.filter(x => x.state === 'running' || x.state === 'waiting').length;
    // group summary dot = most urgent member state
    const prio = ['waiting', 'stale', 'running', 'done', 'ended'];
    const gstate = prio.find(p => g.arr.some(x => stateOf(x) === p)) || 'done';
    html += '<div class="grp" data-g="' + esc(g.k) + '">' +
      '<span class="tri">' + (collapsed ? '▸' : '▾') + '</span>' +
      '<span class="dot gdot ' + gstate + '"></span>' +
      '<span class="gname">' + esc(g.arr[0].project) + '</span>' +
      '<span class="gcnt">' + (activeN ? activeN + '/' : '') + g.arr.length + '</span></div>';
    if (!collapsed) html += g.arr.map(x => rowHtml(x, s.now)).join('');
  }
  list.innerHTML = html;
}

async function refresh() {
  const r = await notchany.invoke('refresh');
  if (r && r.ok) render(r);
}

async function installHooks(b) {
  const label = b.textContent;
  b.disabled = true;
  b.textContent = t('setup_busy');
  const r = await notchany.invoke('install-hooks');
  if (r && r.ok) {
    render(r, true);
  } else {
    b.disabled = false;
    b.textContent = label === t('setup_busy') ? t('setup_fail') : label;
  }
}

async function focusSession(row) {
  row.classList.add('busy');
  const r = await notchany.invoke('focus', { sid: row.dataset.sid });
  row.classList.remove('busy');
  const outcome = r && r.ok && r.state ? r.state.focus_result : (r && r.error ? r.error.code : 'error');
  console.log('focus:', outcome);
  if (r && r.ok) render(r);
}

document.addEventListener('click', e => {
  const el = e.target;
  if (el && (el.id === 'setupBtn' || el.id === 'hookPill')) return installHooks(el);
  if (el && el.id === 'clearDone') {
    notchany.invoke('clear-done').then(r => { if (r && r.ok) render(r); });
    return;
  }
  const clr = el && el.closest ? el.closest('.clr') : null;
  if (clr) {
    notchany.invoke('clear', { sid: clr.dataset.clear }).then(r => { if (r && r.ok) render(r); });
    return;
  }
  const grp = el && el.closest ? el.closest('.grp') : null;
  if (grp) {
    folds[grp.dataset.g] = !folds[grp.dataset.g];
    if (lastRes) render(lastRes, true);
    return;
  }
  const row = el && el.closest ? el.closest('.row.navi') : null;
  if (row && row.dataset.sid) focusSession(row);
});

notchany.addEventListener('statechange', () => render(notchany.state));
notchany.addEventListener('visibilitychange', () => {
  if (notchany.visible) {
    refresh();
    timer = setInterval(refresh, 5000);
  } else if (timer) {
    clearInterval(timer);
    timer = 0;
  }
});

$('#title').textContent = t('title');
$('#clearDone').textContent = t('clear_done');
$('#hookPill').textContent = t('hook_pill');
$('#setupMsg').textContent = t('setup_needed');
$('#setupBtn').textContent = t('setup_btn');
$('#setupNote').textContent = t('setup_note');
if (notchany.state) render(notchany.state);
